INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (8, 'ANNOUNCEMENT FROM THE CABUYAO CITY VETERINARY OFFICE', 'To All Cabuyeño Pet Owners:
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (10, 'Staff Bulletin: Outreach Duty Roster', 'Kindly check the updated duty roster for the Free Anti-Rabies Vaccination Drive on September 19 at Casile. Assignments are posted at the office and on the dashboard. Please coordinate with the barangay volunteers.', NULL, 'Staff', '2026-09-10T22:06:27.000Z', 1, '2026-09-10T22:06:27.000Z', 209, '2026-09-11T07:06:27.000Z', '2026-09-11T07:06:27.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (11, 'Reminder: Renew Your Pet''s Annual Registration', 'Good day! Please update your pet''s registration record with the City Veterinary Office. Keeping ownership details current helps us reach you quickly in emergencies. Visit your account to check your pet''s records.', NULL, 'Owner', '2026-09-08T23:06:27.000Z', 1, '2026-09-08T23:06:27.000Z', 209, '2026-09-11T07:06:27.000Z', '2026-09-11T07:06:27.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (12, 'Free Anti-Rabies Vaccination Drive at Casile', 'The City Veterinary Office will hold a free anti-rabies vaccination drive at Brgy. Casile. Walk-ins are welcome. Please bring your pet''s records.', NULL, 'All', '2026-09-12T20:00:00.000Z', 1, '2026-09-12T20:00:00.000Z', 219, '2026-09-16T07:58:18.000Z', '2026-09-16T07:58:18.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (13, 'Barangay Level Outreach: Banlic', 'A free deworming and vaccination outreach will be conducted at Banlic. Pre-registration via QR is required.', NULL, 'Owner', '2026-09-12T20:00:00.000Z', 1, '2026-09-12T20:00:00.000Z', 219, '2026-09-16T07:58:18.000Z', '2026-09-16T07:58:18.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (14, 'Clinic Schedule Reminder', 'Reminder that the City Veterinary Clinic observes a half-day schedule every first Monday of the month for inventory and maintenance.', NULL, 'All', '2026-09-15T20:00:00.000Z', 1, '2026-09-15T20:00:00.000Z', 219, '2026-09-16T07:58:18.000Z', '2026-09-16T07:58:18.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (15, 'Pet Registration Renewal Opening', 'Annual pet registration renewal is now open. Owners can update their pet records online to stay compliant with the barangay ordinance.', NULL, 'Owner', '2026-09-13T20:00:00.000Z', 1, '2026-09-13T20:00:00.000Z', 219, '2026-09-16T07:58:18.000Z', '2026-09-16T07:58:18.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (16, 'Staff Bulletin: Digital Check-in Update', 'Staff are reminded to use the digital check-in upon arrival. Check-in logs are recorded in the activity audit trail.', NULL, 'Staff', '2026-09-14T20:00:00.000Z', 1, '2026-09-14T20:00:00.000Z', 219, '2026-09-16T07:58:18.000Z', '2026-09-16T07:58:18.000Z') ON CONFLICT DO NOTHING;
INSERT INTO "announcements" ("id", "title", "message", "image", "audience", "scheduled_at", "is_sent", "sent_at", "created_by", "created_at", "updated_at") VALUES (17, 'Rabies Awareness Seminar', 'In partnership with the Department of Health, a free rabies awareness seminar will be held at the City Hall. Pet owners are encouraged to attend.', NULL, 'Owner', '2026-09-13T20:00:00.000Z', 1, '2026-09-13T20:00:00.000Z', 219, '2026-09-16T07:58:18.000Z', '2026-09-16T07:58:18.000Z') ON CONFLICT DO NOTHING;
